/**
 * Tests for the two parsers that read data the network hands us in formats we
 * do not control: OCSP DER and HTTP headers.
 *
 * The OCSP fixture is a real response generated by lab/make-certs.sh, because
 * the interesting bugs live in the DER layering (the DEFAULT version field and
 * the OCTET STRING wrapper), which synthetic stubs tend to get wrong.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { parseOcspStatus } from '../src/tls/ocsp.ts';
import { parseHsts, parseHttpHead } from '../src/tls/hsts.ts';

const here = dirname(fileURLToPath(import.meta.url));
const ocspDer = readFileSync(resolve(here, 'fixtures-ocsp-good.der'));

test('OCSP: a real "good" response parses to good', () => {
  assert.equal(parseOcspStatus(ocspDer), 'good');
});

test('OCSP: garbage and truncation never throw', () => {
  assert.equal(parseOcspStatus(Buffer.alloc(0)), undefined);
  assert.equal(parseOcspStatus(Buffer.from([0x30])), undefined);
  assert.equal(parseOcspStatus(Buffer.from('not der at all', 'utf8')), undefined);
  // Truncate the real response at many points; none may throw.
  for (const cut of [1, 4, 12, 40, 200, 600, ocspDer.length - 20]) {
    assert.equal(parseOcspStatus(ocspDer.subarray(0, cut)), undefined);
  }
});

test('OCSP: a non-successful responseStatus is not reported as a status', () => {
  // OCSPResponse with responseStatus = 3 (tryLater) and no responseBytes.
  const tryLater = Buffer.from([0x30, 0x03, 0x0a, 0x01, 0x03]);
  assert.equal(parseOcspStatus(tryLater), undefined, 'tryLater must not be read as a certificate status');
});

test('HSTS: full modern header', () => {
  const p = parseHsts('max-age=31536000; includeSubDomains; preload');
  assert.equal(p.maxAge, 31536000);
  assert.equal(p.includeSubDomains, true);
  assert.equal(p.preload, true);
  assert.deepEqual(p.problems, []);
});

test('HSTS: case and spacing are tolerated (directive names are case-insensitive)', () => {
  const p = parseHsts('MAX-AGE = 600 ; IncludeSubDomains');
  assert.equal(p.maxAge, 600);
  assert.equal(p.includeSubDomains, true);
});

test('HSTS: missing max-age is a problem', () => {
  const p = parseHsts('includeSubDomains');
  assert.equal(p.maxAge, undefined);
  assert.ok(p.problems.some((x) => /max-age directive is missing/.test(x)));
});

test('HSTS: non-numeric max-age is reported, not coerced', () => {
  const p = parseHsts('max-age=forever');
  assert.equal(p.maxAge, undefined);
  assert.ok(p.problems.some((x) => /not a non-negative integer/.test(x)));
});

test('HSTS: negative max-age is rejected', () => {
  const p = parseHsts('max-age=-1');
  assert.equal(p.maxAge, undefined);
  assert.ok(p.problems.some((x) => /not a non-negative integer/.test(x)));
});

test('HSTS: duplicate max-age is reported', () => {
  const p = parseHsts('max-age=100; max-age=200');
  assert.equal(p.maxAge, 100, 'first value wins for display');
  assert.ok(p.problems.some((x) => /more than once/.test(x)));
});

test('HSTS: unknown directives are ignored per RFC 6797', () => {
  const p = parseHsts('max-age=100; report-uri=https://x; foo');
  assert.equal(p.maxAge, 100);
  assert.deepEqual(p.problems, []);
});

test('HSTS: empty header value yields a missing-max-age problem', () => {
  const p = parseHsts('');
  assert.equal(p.maxAge, undefined);
  assert.ok(p.problems.length > 0);
});

test('HTTP head: status line and header case are handled', () => {
  const head = 'HTTP/1.1 200 OK\r\nSTRICT-TRANSPORT-SECURITY: max-age=100\r\nContent-Type: text/plain';
  const parsed = parseHttpHead(head);
  assert.ok(parsed);
  assert.equal(parsed!.status, 200);
  assert.deepEqual(parsed!.sts, ['max-age=100']);
});

test('HTTP head: multiple HSTS headers are all returned so duplicates can be detected', () => {
  const head = 'HTTP/1.1 200 OK\r\nStrict-Transport-Security: max-age=100\r\nStrict-Transport-Security: max-age=100';
  const parsed = parseHttpHead(head);
  assert.ok(parsed);
  assert.equal(parsed!.sts.length, 2);
});

test('HTTP head: no HSTS header yields an empty list, not undefined', () => {
  const parsed = parseHttpHead('HTTP/1.0 200 ok\r\nContent-type: text/html');
  assert.ok(parsed);
  assert.deepEqual(parsed!.sts, []);
});

test('HTTP head: a non-HTTP response is rejected', () => {
  assert.equal(parseHttpHead('not a response'), undefined);
  assert.equal(parseHttpHead(''), undefined);
});
